
-- V1: Create the application identity and authentication schema.
-- UUID values will be generated by the Java application.

CREATE TABLE app_users (
    id UUID PRIMARY KEY,

    email VARCHAR(320) NOT NULL,
    email_normalized VARCHAR(320) NOT NULL,

    -- Nullable because Google-only accounts do not require passwords.
    -- Local passwords will use Argon2id hashes.
    password_hash VARCHAR(255),

    email_verified_at TIMESTAMPTZ,

    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',

    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT uq_app_users_email_normalized
        UNIQUE (email_normalized),

    CONSTRAINT chk_app_users_email
        CHECK (length(trim(email)) > 0),

    CONSTRAINT chk_app_users_email_normalized
        CHECK (
            email_normalized = lower(trim(email_normalized))
        ),

    CONSTRAINT chk_app_users_status
        CHECK (status IN ('ACTIVE', 'LOCKED', 'DISABLED'))
);


CREATE TABLE user_profiles (
    user_id UUID PRIMARY KEY,

    full_name VARCHAR(200),
    avatar_url TEXT,

    currency_preference VARCHAR(3) NOT NULL DEFAULT 'USD',
    timezone VARCHAR(64) NOT NULL DEFAULT 'UTC',

    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_user_profiles_user
        FOREIGN KEY (user_id)
        REFERENCES app_users(id)
        ON DELETE CASCADE,

    CONSTRAINT chk_user_profiles_currency
        CHECK (currency_preference ~ '^[A-Z]{3}$')
);


CREATE TABLE oauth_identities (
    id UUID PRIMARY KEY,

    user_id UUID NOT NULL,

    provider VARCHAR(30) NOT NULL,
    provider_subject VARCHAR(255) NOT NULL,
    provider_email VARCHAR(320),

    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_oauth_identities_user
        FOREIGN KEY (user_id)
        REFERENCES app_users(id)
        ON DELETE CASCADE,

    CONSTRAINT uq_oauth_provider_subject
        UNIQUE (provider, provider_subject),

    CONSTRAINT chk_oauth_provider
        CHECK (provider IN ('GOOGLE'))
);


CREATE INDEX idx_oauth_identities_user_id
    ON oauth_identities(user_id);


CREATE TABLE user_sessions (
    id UUID PRIMARY KEY,

    user_id UUID NOT NULL,

    -- SHA-256 hexadecimal digest of the refresh token.
    -- Never store the actual refresh token.
    refresh_token_hash CHAR(64) NOT NULL UNIQUE,

    -- Used to identify related sessions during token rotation.
    token_family_id UUID NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMPTZ NOT NULL,
    last_used_at TIMESTAMPTZ,

    revoked_at TIMESTAMPTZ,
    revocation_reason VARCHAR(100),

    replaced_by_session_id UUID,

    user_agent TEXT,
    ip_address VARCHAR(45),

    CONSTRAINT fk_user_sessions_user
        FOREIGN KEY (user_id)
        REFERENCES app_users(id)
        ON DELETE CASCADE,

    CONSTRAINT fk_user_sessions_replacement
        FOREIGN KEY (replaced_by_session_id)
        REFERENCES user_sessions(id)
        ON DELETE SET NULL,

    CONSTRAINT chk_user_sessions_token_hash
        CHECK (refresh_token_hash ~ '^[0-9a-f]{64}$'),

    CONSTRAINT chk_user_sessions_expiration
        CHECK (expires_at > created_at)
);


CREATE INDEX idx_user_sessions_user_id
    ON user_sessions(user_id);

CREATE INDEX idx_user_sessions_token_family
    ON user_sessions(token_family_id);

CREATE INDEX idx_user_sessions_active_expiration
    ON user_sessions(expires_at)
    WHERE revoked_at IS NULL;
